  void initValue(SalesType _salesType)
{
    next initValue(_salesType);

    this.AIBBookTable = this.salesTable().AIBBookTable;
}

public Common AIBFantasyBookLookup(FormReferenceControl _formReferenceControl)
{
    SysReferenceTableLookup refTableLookup = SysReferenceTableLookup::newParameters(tableNum(AIBBookTable), _formReferenceControl);

    refTableLookup.parmQuery(this.AIBGetFantasyBookLookupQuery());
    refTableLookup.addLookupfield(fieldNum(AIBBookTable, Id));
    refTableLookup.addLookupfield(fieldNum(AIBBookTable, Name));
    refTableLookup.addLookupfield(fieldNum(AIBBookTable, Genre));
    refTableLookup.addLookupfield(fieldNum(AIBBookTable, Author));

    return refTableLookup.performFormLookup();
}
